{
  "name": "BACnet楼宇自动化控制器",
  "name_en": "BACnet Building Automation Controller",
  "manufacturer": "",
  "description": "这是一类支持 BACnet 协议的楼宇自动化现场设备或控制器，常用于连接和管理暖通空调、环境传感器、执行器、电表、报警点位等。它可在网络中发布设备与对象信息，并允许读取或写入各类点位属性。在实验室或科研设施中，这类设备常用于房间环境监测、空调与通风联动、能耗采集以及楼宇基础设施集成。",
  "description_en": "This is a BACnet-compatible building automation field device or controller used to interface with HVAC equipment, environmental sensors, actuators, utility meters, and alarm points. It exposes device and object information on the network and allows properties of points to be read or written. In laboratories and research facilities, such devices are commonly used for room environmental monitoring, HVAC and ventilation coordination, energy data collection, and facility infrastructure integration.",
  "tag_hints": [
    "BACnet MS/TP",
    "building automation",
    "HVAC monitoring",
    "environmental control",
    "property read/write",
    "facility integration"
  ],
  "actions": [
    {
      "action_name": "auto-all_props_results",
      "description": "处理读取对象全部属性后的结果。",
      "description_en": "Process the results of reading all properties of an object."
    },
    {
      "action_name": "auto-confirmation",
      "description": "处理已确认的 BACnet 响应消息。",
      "description_en": "Handle a confirmed BACnet response message."
    },
    {
      "action_name": "auto-fetch_values",
      "description": "抓取设备对象的当前点位值。",
      "description_en": "Fetch current point values from device objects."
    },
    {
      "action_name": "auto-handle_response_for_obj_list",
      "description": "处理设备对象列表读取响应。",
      "description_en": "Handle the response from reading a device object list."
    },
    {
      "action_name": "auto-handle_write_prop_cb",
      "description": "处理属性写入操作的回调结果。",
      "description_en": "Handle the callback result of a property write operation."
    },
    {
      "action_name": "auto-indication",
      "description": "处理传入的 BACnet 指示或上报消息。",
      "description_en": "Handle an incoming BACnet indication or unsolicited message."
    },
    {
      "action_name": "auto-make_rp_for_obj_list",
      "description": "为读取设备对象列表创建请求上下文。",
      "description_en": "Create a request context for reading a device object list."
    },
    {
      "action_name": "auto-process_IAmRequest",
      "description": "处理设备的 I-Am 宣告以识别已发现设备。",
      "description_en": "Process an I-Am announcement to identify a discovered device."
    },
    {
      "action_name": "auto-read_next_object",
      "description": "按顺序读取对象列表中的下一个对象。",
      "description_en": "Read the next object in the object list sequence."
    },
    {
      "action_name": "auto-read_property",
      "description": "读取 BACnet 对象的指定属性。",
      "description_en": "Read a specified property of a BACnet object."
    },
    {
      "action_name": "auto-read_property_callback",
      "description": "处理属性读取操作的回调结果。",
      "description_en": "Handle the callback result of a property read operation."
    },
    {
      "action_name": "auto-request",
      "description": "发送 BACnet 请求消息。",
      "description_en": "Send a BACnet request message."
    },
    {
      "action_name": "auto-run",
      "description": "运行 BACnet 客户端通信循环。",
      "description_en": "Run the BACnet client communication loop."
    },
    {
      "action_name": "auto-set_value_for_prop",
      "description": "设置指定属性的值。",
      "description_en": "Set the value of a specified property."
    },
    {
      "action_name": "auto-start",
      "description": "启动设备通信或轮询流程。",
      "description_en": "Start device communication or polling."
    },
    {
      "action_name": "auto-trim_obj_list",
      "description": "整理并筛选设备对象列表。",
      "description_en": "Trim and filter a device object list."
    },
    {
      "action_name": "auto-who_is",
      "description": "发送 Who-Is 以发现 BACnet 网络中的设备。",
      "description_en": "Send Who-Is to discover devices on the BACnet network."
    },
    {
      "action_name": "auto-write_property",
      "description": "写入 BACnet 对象的指定属性值。",
      "description_en": "Write a specified property value of a BACnet object."
    },
    {
      "action_name": "auto-write_values_to_csv",
      "description": "将当前点位值快照写入 CSV 文件。",
      "description_en": "Write a snapshot of current point values to a CSV file."
    },
    {
      "action_name": "auto-get_values_for_device",
      "description": "获取设备各对象的值。",
      "description_en": "Get the values of a device's objects."
    },
    {
      "action_name": "auto-get_obj_list_for_device",
      "description": "获取设备的对象列表。",
      "description_en": "Get the object list of a device."
    },
    {
      "action_name": "auto-get_address_for_device_id",
      "description": "获取设备 ID 对应的地址。",
      "description_en": "Get the address corresponding to a device ID."
    },
    {
      "action_name": "auto-get_value_for_prop",
      "description": "获取指定属性的值。",
      "description_en": "Get the value of a specified property."
    },
    {
      "action_name": "auto-get_values_for_all_props",
      "description": "获取指定对象全部属性的值。",
      "description_en": "Get the values of all properties of a specified object."
    },
    {
      "action_name": "auto-get_device_db",
      "description": "获取已发现设备数据库。",
      "description_en": "Get the discovered device database."
    },
    {
      "action_name": "auto-get_values_dict",
      "description": "获取采集值字典。",
      "description_en": "Get the collected values dictionary."
    },
    {
      "action_name": "auto-completed",
      "description": "标记一次任务或操作已完成。",
      "description_en": "Mark a task or operation as completed."
    },
    {
      "action_name": "auto-process_task",
      "description": "执行一次周期性任务。",
      "description_en": "Execute one periodic task cycle."
    }
  ]
}

